def feasible_shifts(comp, others):
    # others: dict comp->shift already chosen; None = original
    H,W=None,None
    hs=[]
    for s in range(W):
        ok=True
        for r,c in comp:
            cc=c+s
            if cc>=W: ok=False;break
            for o,os_ in others.items():
                if o is comp: continue
                occ=set((r2+ (1 if os_ else 0) for r2,c2 in o))
                if (r,cc) in occ: ok=False; break
            if not ok: break
        if ok: hs.append(s)
    return hs

