            for dx in range(W-mc,0,-1):
                n=[(r,cc+dx) for r,cc in sc]
                if all(r<H and c<W and res[r][c]==0 for r,c in n):
                    best=dx; break
            if best is None and mc>=W: break
            if best is None: continue
            if best==0 and sum(res[r][c] for r,c in sc)==0: continue
            removed={g[r][c] for r,c in sc}
            for r,c in sc: res[r][c]=0
            for r,c in sc: res[r][c+best]=g[r][c]
            changed=True
        if not changed: break
    return res

