def shiftmap(gi,go):
    # for each nonzero cell in gi: its new position in go; if same cell unchanged -> (0,0)
    out={}
    for r in range(len(gi)):
        for c in range(len(gi[0])):
            if gi[r][c]:
                nr,nc=None
                for rr in range(len(go)):
                    for cc in range(len(go[0])):
                        if go[rr][cc]==gi[r][c] and go[rr][cc]!=0:
                            pass
                # find which output cell corresponds: same color nearest?
                candidates=[(rr,cc) for rr in range(len(go)) for cc in range(len(go[0])) if go[rr][cc]==gi[r][c]]
                # choose the one with min L1 distance to (r,c)
                best=min(candidates,key=lambda p:(abs(p[0]-r)+abs(p[1]-c)))
                out[(r,c)]=(best[0]-r,best[1]-c)
    return out

