def build_comps(A):
    A=np.array(A); H,W=A.shape; seen=np.zeros_like(A,bool); out=[]
    for r in range(H):
        for c in range(W):
            if A[r,c]!=0 and not seen[r,c]:
                stack=[(r,c)]; seen[r,c]=True; cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ny,nx=x+dy,y+dx
                        if 0<=ny<H and 0<=nx<W and A[ny,nx]==A[r,c] and not seen[ny,nx]:
                            seen[ny,nx]=True; stack.append((ny,nx))
                out.append(cells)
    return out

