    orig={(r,c):int(g[r,c]) for r in range(H) for c in range(W) if g[r,c]}
    cs=build_comps(g.tolist())
    bands=[]; cur=[]
    for ci in sorted(cs,key=lambda c:min(r for r,_ in c)):
        tr=min(r for r,_ in ci)
        bb=max(max(r for r,_ in c2) for c2 in cur) if cur else -1
        if cur and tr<=bb:
            cur.append(ci)
        elif cur:
            bands.append(cur); cur=[]
        cur.append(ci)
    if cur: bands.append(cur)
    res=[[0]*W for _ in range(H)]; occ=set(orig.items()); occgrid={p:(orig[p]) for p in orig}
    for band in reversed(bands):
        for ci in sorted(band,key=lambda c:-max(c for _,c in c)):
            cm=max(c for _,c in ci)
            # search d decreasing
            bs=None
            for d in range(W-1-cm, -1, -1):
                cand=[(r,c+d) for r,c in ci]
                ok=True
                for r,cc in cand:
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            nb=(r+dr,cc+dc)
                            if 0<=nb[0]<H and 0<=nb[1]<W and nb in occgrid:
                                ok=False; break
                        if not ok: break
                    if not ok: break
                if ok: bs=d; break
            if bs is None: bs=W-1-cm
            for r,c in ci:
                res[r][c+bs]=int(g[r][c]); 
                occ[(r,c+bs)]=res[r][c+bs];
    return res

