# Variant A: order = bottom-up bands, within-band right-to-left; block on Chebyshev adjacency to already-placed OR original cells
def f_v1(g, block='adjboth'):
    g=np.array(g); H,W=g.shape
    cs=build_comps(g.tolist())
    # sort by max row descending (bottom up), then by max col descending within
    order=sorted(cs,key=lambda c:(-max(r for r,_ in c), -max(c for _,c in c)))
    occ={}  # final positions (color)
    res=[[0]*W for _ in range(H)]
    for ci in order:
        key=int(g[ci[0][0],ci[0][1]])
        cm=max(c for _,c in ci)
        best=None
        for d in range(W-1-cm,-1,-1):
            cand={(r,c+d):key for r,c in ci}
            ok=True
            for p,k in cand.items():
                r_,c_=p
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        nb=(r_+dr,c_+dc)
                        if 0<=nb[0]<H and 0<=nb[1]<W and nb in occ and occ[nb]!=k:
                            ok=False; break
                    if not ok: break
                if not ok: break
            if ok: best=d; break
        shift=best if best is not None else W-1-cm
        for r,c in ci:
            res[r][c+shift]=int(g[r][c]); occ[(r,c+shift)]=int(g[r][c])
