# Rule: process components top->bottom (row asc, then col asc); each slides right as far as possible
# until hitting the wall or a cell already occupied by an earlier component.
def f(g):
    g=np.array(g); H,W=g.shape; cs=comps(g)
    o=sorted(cs,key=lambda c:(min(r for r,_ in c), min(c for _,c in c)))
    res=[[0]*W for _ in range(H)]; placed=set()
    for ci in o:
        # sliding right: max d such that all cells free
        best=None
        for d in range(0,W):
            P={(r,x+d) for r,x in ci}
            if all(rr<(H) and cc<W and (rr,cc) not in placed for rr,cc in P) and max(x for _,x in ci)+d<=W-1:
                pass
            else: break
        # find largest d with full fit
        d=0
        while True:
            P={(r,x+d) for r,x in ci}
            if any(rr>=H or cc>=W or (rr,cc) in placed for rr,cc in P):
                break
            d+=1
            if max(x for _,x in ci)+d==W: break
        if d==0: continue
        # slide to d-1
        final_d=d-1
        for r,cx in ci:
            res[r][cx+final_d]=int(g[r][cx]); placed.add((r,cx+final_d))
    return res

